import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.model.Element;
import org.joget.apps.form.model.FormData;
import org.joget.apps.form.model.FormRow;
import org.joget.apps.form.model.FormRowSet;
import org.joget.apps.form.service.FormUtil;

import java.util.Calendar;

public FormRowSet load(Element element, String primaryKey, FormData formData) {
    FormRowSet rows = new FormRowSet();

    // Add default value "--"
    FormRow defaultOption = new FormRow();
    defaultOption.setProperty(FormUtil.PROPERTY_VALUE, "--");
    defaultOption.setProperty(FormUtil.PROPERTY_LABEL, "--");
    rows.add(defaultOption);

    int currentYear = Calendar.getInstance().get(Calendar.YEAR);
    for (int year = currentYear; year >= 1950; year--) {
        FormRow option = new FormRow();
        option.setProperty(FormUtil.PROPERTY_VALUE, String.valueOf(year));
        option.setProperty(FormUtil.PROPERTY_LABEL, String.valueOf(year));
        rows.add(option);
    }

    return rows;
}

// Call load method with injected variables
return load(element, primaryKey, formData);

import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.model.Element;
import org.joget.apps.form.model.Form;
import org.joget.apps.form.model.FormData;
import org.joget.apps.form.service.FormUtil;


    public boolean validate(Element element, FormData formData, String[] values) {
        boolean result = true; // Initialize result to true
        try {
            Form form = FormUtil.findRootForm(element);
            
            // Get the starting year
            String field1Id = "annee_debut";
            Element field1 = FormUtil.findElement(field1Id, form, formData);
            String[] idmaster1 = FormUtil.getElementPropertyValues(field1, formData);
            String recordid1 = String.valueOf(idmaster1[0]);

            // Get the ending year
            String field2Id = "annee_fin";
            Element field2 = FormUtil.findElement(field2Id, form, formData);
            String[] idmaster2 = FormUtil.getElementPropertyValues(field2, formData);
            String recordid2 = String.valueOf(idmaster2[0]);

            // Compare the years
            if (Integer.parseInt(recordid1) > Integer.parseInt(recordid2)) {
                result = false;
                String id = FormUtil.getElementParameterName(element);
                formData.addFormError(id, "L'année de début doit être antérieure à l'année de fin.");
            }
        } catch (Exception e) {
            result = false;
            e.printStackTrace(); // Log exception for debugging
        }

        return result;
    }


return validate(element, formData, values);

